function animateSpatial(){if(!spatial.expanded)return;spatial.blend+=(1-spatial.blend)*.07;floorGroups.forEach((g,k)=>{g.position.y=2+k*(3+6*spatial.blend);const p=new T.Vector3(data[0][1]-28,g.position.y+1,data[0][2]).project(camera),el=floorLabels[k];el.hidden=p.z>1||!g.visible;el.style.left=(p.x*.5+.5)*innerWidth+'px';el.style.top=(-p.y*.5+.5)*innerHeight+'px';el.classList.toggle('active',k+1===spatial.floor)})}

function statusText(d){return !d.online?'离线':d.type==='light'?(d.running?'照明开启':'照明关闭'):d.type==='access'?(d.running?'门禁解锁':'门禁锁定'):d.type==='camera'?(d.running?'监控运行':'监控待机'):'采集中'}
function focusBuilding(i,device=null){selected=i;auto=false;$('#rotate').classList.remove('on');const r=data[i];desiredTarget.set(r[1],0,r[2]);desiredRadius=220;marker.position.set(r[1],1.5,r[2]);marker.scale.set(r[3]/15,r[5]/15,1);marker.visible=true;highlight.setFromObject(buildings[i]);highlight.visible=true;highlight.material.color.set(currentAlert&&!currentAlert.resolved?0xf1bc77:0x72eac9);deviceFocus=device;beacon.visible=!!device;if(device){beacon.position.set(r[1]+r[3]/2+.9,r[4]*.7,r[2]+r[5]/3);beacon.material.color.set(0xffc27a)}document.querySelectorAll('#buildings button').forEach((b,k)=>b.classList.toggle('selected',k===i))}
function openBuilding(i,tab='rooms'){closeSpatial();currentAlert=null;detailTab=tab;currentRoom=rooms.find(r=>r.bi===i);deviceFilter='all';focusBuilding(i);renderDetail()}
function openAlert(id){closeSpatial();currentAlert=alerts.find(a=>a.id===id);if(!currentAlert)return;currentRoom=rooms.find(r=>r.id===currentAlert.room);detailTab='alerts';focusBuilding(currentAlert.bi,currentAlert.device);renderDetail();toast(`已定位：${data[currentAlert.bi][0]} · ${currentRoom.name}`)}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&spatial.open){closeSpatial();$('#reset').click();return}if(e.key==='Escape'&&!$('#detail').hidden)$('#detail .close').click()});
function roomEquipment(){return equipment.filter(d=>d.room===currentRoom.id)}
function deviceList(list){if(!list.length)return '<div class="empty-state">当前筛选下暂无设备</div>';return list.map(d=>`<div class="equipment-card ${deviceFocus===d.id?'focused':''}"><div class="equipment-top"><span class="equip-icon">${{light:'☼',camera:'◉',access:'⌑',sensor:'❖'}[d.type]}</span><div><b>${d.name}</b><small>${d.serial}</small></div><span class="state-chip ${d.online?'':'warning'}">${d.online?'在线':'离线'}</span></div><div class="equipment-bottom"><span>${statusText(d)}</span><div><button data-locate="${d.id}">定位</button>${d.type==='light'||d.type==='access'?`<button data-toggle="${d.id}" ${!d.online?'disabled':''}>${d.type==='light'?(d.running?'关闭照明':'开启照明'):(d.running?'锁定门禁':'解锁门禁')}</button>`:''}</div></div></div>`).join('')}
function renderDetail(){const i=selected,r=data[i],rms=rooms.filter(x=>x.bi===i),devs=equipment.filter(d=>d.bi===i),active=alerts.filter(a=>a.bi===i&&!a.resolved);$('#detail').hidden=false;$('#detail').innerHTML=`<div class="detail-head"><div><div class="eyebrow">SPACE 0${i+1} · 模拟空间</div><h2>${r[0]}</h2></div><button class="close" aria-label="关闭">×</button></div><div class="detail-summary"><span>${r[7]} 层 · ${rms.length} 间房间</span><span>${devs.filter(d=>d.online).length}/${devs.length} 设备在线</span><span class="${active.length?'warn-text':'good-text'}">${active.length?active.length+' 项待关注':'无待处理告警'}</span></div><div class="detail-tabs"><button id="openSpatialFromDetail">楼层空间</button><button data-detail="rooms" class="${detailTab==='rooms'?'active':''}">房间信息</button><button data-detail="devices" class="${detailTab==='devices'?'active':''}">设备管理</button><button data-detail="alerts" class="${detailTab==='alerts'?'active':''}">告警联动 ${active.length?`<sup>${active.length}</sup>`:''}</button></div><div class="detail-content">${detailTab==='alerts'?renderAlerts():`<div class="space-select"><label>楼层<select id="floorSelect" aria-label="选择楼层">${Array.from({length:r[7]},(_,k)=>`<option value="${k+1}" ${currentRoom.floor===k+1?'selected':''}>${k+1}F</option>`).join('')}</select></label><label>房间<select id="roomSelect" aria-label="选择房间">${rms.filter(x=>x.floor===currentRoom.floor).map(x=>`<option value="${x.id}" ${x.id===currentRoom.id?'selected':''}>${x.name}</option>`).join('')}</select></label><span class="state-chip ${currentRoom.occupied?'':'idle'}">${currentRoom.occupied?'使用中':'空闲'}</span></div>${detailTab==='rooms'?renderRoom():renderDevices()}`}</div><div class="detail-foot"><i></i> 模拟数据 · 操作仅在本次页面会话生效</div>`;
 $('#openSpatialFromDetail').onclick=()=>openSpatial(selected,currentRoom.id,deviceFocus);$('#detail .close').onclick=()=>{$('#detail').hidden=true;highlight.visible=false;beacon.visible=false;marker.visible=false};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detail;renderDetail()});if($('#floorSelect'))$('#floorSelect').onchange=e=>{currentRoom=rms.find(x=>x.floor===+e.target.value);deviceFocus=null;beacon.visible=false;renderDetail()};if($('#roomSelect'))$('#roomSelect').onchange=e=>{currentRoom=rooms.find(x=>x.id===e.target.value);deviceFocus=null;beacon.visible=false;renderDetail()};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const d=equipment.find(x=>x.id===b.dataset.toggle);if(!d.online)return;d.running=!d.running;renderDetail();updateOverview();toast(`${currentRoom.name} · ${statusText(d)}（模拟）`)});document.querySelectorAll('[data-locate]').forEach(b=>b.onclick=()=>{deviceFocus=b.dataset.locate;focusBuilding(i,deviceFocus);renderDetail();toast('设备位置为楼栋级示意点')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{deviceFilter=b.dataset.filter;renderDetail()});document.querySelectorAll('[data-open-alert]').forEach(b=>b.onclick=()=>openAlert(b.dataset.openAlert));const event=currentAlert||alerts.find(a=>a.bi===selected);if($('#ackAlert'))$('#ackAlert').onclick=()=>acknowledgeEvent(event);if($('#handleAlert'))$('#handleAlert').onclick=()=>handleEvent(event);if($('#recoverAlert'))$('#recoverAlert').onclick=()=>recoverEvent(event);}

function renderRoom(){const x=currentRoom;return `<div class="room-title"><h3>${x.name}</h3><small>${x.occupied?'当前课程：智慧课堂 · 使用至 16:40':'暂无课程安排 · 可使用'}</small></div><div class="room-environment"><div class="${x.temp>30?'hot':''}"><span>温度</span><b>${x.temp.toFixed(1)}<small>°C</small></b><em>${x.temp>30?'高于阈值':'舒适'}</em></div><div><span>湿度</span><b>${x.humidity}<small>%</small></b><em>正常</em></div><div><span>空气质量</span><b>${x.aqi}<small>AQI</small></b><em>优</em></div></div><div class="minor-line">PM2.5 ${x.pm} μg/m³ <span>温度阈值 30°C · 楼层传感数据模拟</span></div><div class="subheading">关联设备 <small>${roomEquipment().length} 台</small></div>${deviceList(roomEquipment())}`}
function renderDevices(){let ds=[...roomEquipment(),...equipment.filter(d=>d.bi===selected&&d.type==='sensor')].filter(d=>deviceFilter==='offline'?!d.online:deviceFilter==='online'?d.online:true);return `<div class="filter-row"><span>房间与楼栋设备</span>${[['all','全部'],['online','在线'],['offline','离线']].map(([v,n])=>`<button data-filter="${v}" class="${deviceFilter===v?'active':''}">${n}</button>`).join('')}</div>${deviceList(ds)}`}
// Explainable rule simulation; no remote AI or real device commands.
const opsStart=Date.now();
const opsLog=[];
alerts.forEach(a=>{a.handled=false;a.records=[{label:'规则检测到异常',at:opsStart-120000},{label:'已关联建筑、房间与设备',at:opsStart-115000}];a.history=a.id==='heat'?[24.8,25.1,26.2,27.4,28.7,30.2,31.1,31.8,32.6]:[1,1,1,1,0,0,0,0,0]});
const initialEquipment=equipment.map(d=>({id:d.id,online:d.online,running:d.running}));
function recordEvent(a,label){a.records.push({label,at:Date.now()});opsLog.push({event:a.id,label,at:Date.now()})}
function acknowledgeEvent(a){if(a.resolved||a.ack)return;a.ack=true;recordEvent(a,'值班人员已确认（模拟）');refreshOps(a)}
function handleEvent(a){if(a.resolved||!a.ack||a.handled)return;a.handled=true;recordEvent(a,a.id==='heat'?'已记录通风与空调排查（模拟）':'已记录网络与供电排查（模拟）');refreshOps(a)}
function recoverEvent(a){if(a.resolved||!a.handled)return;a.resolved=true;if(a.id==='heat'){hotRoom.temp=24.8;a.history.push(28.3,26.1,24.8)}else {badCamera.online=true;a.history.push(1,1,1)}recordEvent(a,a.id==='heat'?'复测 24.8°C，规则校验通过':'连续 3 次心跳正常，规则校验通过');recordEvent(a,'事件已关闭（模拟）');highlight.material.color.set(0x72eac9);beacon.visible=false;refreshOps(a)}
function refreshOps(a){if(currentAlert?.id===a.id||selected===a.bi)renderDetail();updateOverview()}
function trendSvg(a){let values=a.history,min=a.id==='heat'?20:0,max=a.id==='heat'?36:1.2;const points=values.map((v,i)=>`${8+i/(values.length-1)*324},${76-(v-min)/(max-min)*64}`).join(' '),threshold=76-(30-20)/16*64;return `<svg class="ops-chart" viewBox="0 0 340 92" role="img" aria-label="${a.id==='heat'?'模拟温度采样趋势':'模拟设备心跳趋势'}"><defs><linearGradient id="opsfill" x2="0" y2="1"><stop stop-color="#a3e4ca" stop-opacity=".2"/><stop offset="1" stop-color="#a3e4ca" stop-opacity="0"/></linearGradient></defs><path d="M8 76H332M8 44H332M8 12H332" stroke="#b4d4ce15" fill="none"/>${a.id==='heat'?`<path d="M8 ${threshold}H332" stroke="#e5bd7b88" stroke-dasharray="4 4"/><text x="286" y="${threshold-5}" fill="#c4ac85" font-size="8">30°C 阈值</text>`:''}<polygon points="8,78 ${points} 332,78" fill="url(#opsfill)"/><polyline points="${points}" fill="none" stroke="${a.resolved?'#9ee3c5':'#e8c58d'}" stroke-width="2"/><text x="8" y="90" fill="#94b4bf" font-size="8">${a.id==='heat'?'每 2 分钟采样':'每次心跳检测'} · 模拟序列</text><text x="307" y="90" fill="#94b4bf" font-size="8">最近</text></svg>`}
function renderAlerts(){const a=currentAlert||alerts.find(x=>x.bi===selected);if(!a)return '<div class="empty-state">✓ 当前建筑暂无演示告警</div>';const x=rooms.find(r=>r.id===a.room),dev=equipment.find(d=>d.id===a.device);return `<div class="ops-header"><span class="state-chip ${a.resolved?'':'warning'}">${a.resolved?'已恢复':a.handled?'待复测':a.ack?'已确认':'待确认'}</span><span>◇ 模拟规则分析</span></div><div class="ops-primary"><div><h3>${a.title}</h3><p>${data[a.bi][0]} · ${x.name}</p></div><strong class="${a.resolved?'good-text':''}">${a.resolved?(a.id==='heat'?'24.8°C':'心跳正常'):a.id==='heat'?'32.6°C':'离线'}</strong></div><div class="ops-section"><div class="subheading">${a.id==='heat'?'温度变化趋势':'设备心跳趋势'}<small>${a.resolved?'复测已通过':'异常采样记录'}</small></div>${trendSvg(a)}</div><div class="impact-grid"><div><b>1</b><span>${a.resolved?(a.id==='heat'?'原影响教室':'原影响阅览室'):(a.id==='heat'?'受影响教室':'受影响阅览室')}</span></div><div><b>${a.id==='heat'?'3':'1'}</b><span>${a.id==='heat'?'关联设备':a.resolved?'已恢复画面':'不可用画面'}</span></div><div><b>${a.id==='heat'?(x.occupied?'使用中':'空闲'):'门禁正常'}</b><span>${a.id==='heat'?'房间状态':'关联门禁状态'}</span></div></div><div class="rule-note"><b>${a.resolved?'历史触发依据':'规则依据'}</b><p>${a.id==='heat'?'连续 3 次以上采样高于 30°C：30.2 → 31.1 → 31.8 → 32.6°C。':'连续 3 次以上心跳未到达，且目标设备在线标记为离线。'}</p><small>用于讲解的确定性规则，非真实 AI 诊断。</small></div><div class="intelligence-note">◇ 建议处置 <span>${a.id==='heat'?'核查传感器 → 检查通风及空调 → 复测温度 → 关闭事件。':'检查供电与网络 → 确认设备恢复 → 验证连续心跳 → 关闭事件。'}</span></div><div class="alarm-link">${dev.name} · ${dev.serial}<small>场景点位为楼栋级示意，未建立室内精确模型</small></div><div class="subheading">处置时间线 <small>本次模拟会话</small></div><ol class="event-timeline">${a.records.map((r,i)=>`<li class="${i===a.records.length-1?'latest':''}"><i></i><span>${r.label}</span><time>${new Date(r.at).toLocaleTimeString('zh-CN',{hour12:false})}</time></li>`).join('')}</ol><div class="alarm-actions"><button data-open-alert="${a.id}">定位</button>${!a.resolved?`<button id="ackAlert" ${a.ack?'disabled':''}>${a.ack?'已确认':'确认告警'}</button><button id="handleAlert" ${!a.ack||a.handled?'disabled':''}>${a.handled?'已排查':'模拟排查'}</button><button id="recoverAlert" ${!a.handled?'disabled':''}>复测并恢复</button>`:'<span class="closed-note">✓ 处置闭环已完成</span>'}</div>`}
function resetSimulation(){equipment.forEach(d=>Object.assign(d,initialEquipment.find(x=>x.id===d.id)));hotRoom.temp=32.6;alerts.forEach(a=>{a.ack=false;a.handled=false;a.resolved=false;a.history=a.id==='heat'?[24.8,25.1,26.2,27.4,28.7,30.2,31.1,31.8,32.6]:[1,1,1,1,0,0,0,0,0];a.records=[{label:'规则检测到异常',at:Date.now()-120000},{label:'已关联建筑、房间与设备',at:Date.now()-115000}]});opsLog.length=0;updateOverview();$('#reset').click()}

