function syncIndoorDevices(){for(const [id,m] of walk.fixtures){const d=equipment.find(e=>e.id===id);if(d?.type==='light'&&m.material)m.material.emissiveIntensity=d.online&&d.running?.75:0}for(const [id,bank] of walk.lightBanks||[]){const d=equipment.find(e=>e.id===id);bank.forEach(m=>m.emissiveIntensity=d.online&&d.running?.65:0)}for(const [id,l] of walk.roomLights||[]){const d=equipment.find(e=>e.id===id);l.intensity=d.online&&d.running?9:.4}for(const [id,m] of walk.deviceIndicators||[]){const d=equipment.find(e=>e.id===id);m.color.set(!d.online?'#eac07d':d.running?'#9ce8bc':'#87c6d3')}if(walkHighlight){const m=walk.fixtures.get(walk.device);walkHighlight.visible=!!m;if(m)walkHighlight.setFromObject(m)}}
function openWalk(roomId='B0-301'){if(typeof tour!=='undefined')closeTour();closeSpatial();$('#detail').hidden=true;auto=false;const r=rooms.find(r=>r.id===roomId&&r.bi===0)||hotRoom;walk.active=true;walk.floor=r.floor;walk.room=r.id;walk.x=-22;walk.z=0;walk.yaw=-Math.PI/2;walk.pitch=0;walk.route=false;walk.station=0;walk.last=0;walk.device=null;walk.keys.clear();walk.vx=0;walk.vz=0;walk.speed=walk.speed||2.1;walk.sensitivity=walk.sensitivity||.0032;buildIndoor();walkHUD.hidden=false;document.body.classList.add('indoor','walk-route-min');document.body.classList.remove('walk-devices-open');renderer.toneMappingExposure=1.08;walkCamera.aspect=innerWidth/innerHeight;walkCamera.updateProjectionMatrix();drawWalkHUD();}
document.querySelector('nav').addEventListener('click',()=>{if(walk.active)exitWalk(false)},true);
function exitWalk(toPlan=true){walk.active=false;walk.route=false;walk.keys.clear();walkHUD.hidden=true;document.body.classList.remove('indoor','walk-clean','walk-route-min','walk-devices-open');renderer.toneMappingExposure=1.4;if(toPlan)openSpatial(0,walk.room);else $('#reset').click()}
function canWalk(x,z){const radius=.22;if(x< -23.6||x>23.6||z< -8.55||z>8.55)return false;return !walk.colliders.some(c=>Math.abs(x-c.x)<c.w/2+radius&&Math.abs(z-c.z)<c.d/2+radius)}
function advanceWalk(dx,dz){if(canWalk(walk.x+dx,walk.z))walk.x+=dx;if(canWalk(walk.x,walk.z+dz))walk.z+=dz}
function walkStations(){const r=rooms.find(r=>r.id===walk.room),p=indoorLocation(r),face=p.side<0?0:Math.PI;return [{x:-22,z:0,yaw:-Math.PI/2,pitch:0,title:'走廊入口',copy:'观察楼层导视、门牌与两侧教室。'}, {x:p.x,z:0,yaw:face,pitch:0,title:r.code+' 教室入口',copy:'通过门牌定位房间，门禁与摄像头为可选设备点。'}, {x:p.x,z:p.side*3.1,yaw:face,pitch:0,title:'进入 '+r.code+' 教室',copy:'查看课桌、讲台、黑板、窗户与顶部照明。'}, {x:p.x,z:p.side*7.2,yaw:face+Math.PI,pitch:-.04,title:'教室全景与设备',copy:'查看设备清单，点击照明、门禁或场景设备查询模拟状态。'}, {x:p.x,z:0,yaw:-Math.PI/2,pitch:0,title:'返回走廊',copy:'路线结束，可自由行走，或返回楼层平面继续查看。'}]}
function setWalkStation(n,teleport=false){walk.station=T.MathUtils.clamp(n,0,4);walk.routeHold=0;const p=walkStations()[walk.station];if(teleport){walk.x=p.x;walk.z=p.z;walk.yaw=p.yaw;walk.pitch=p.pitch}drawWalkHUD()}
function startWalkRoute(){document.body.classList.remove('walk-route-min');walk.vx=walk.vz=0;walk.x=-22;walk.z=0;walk.yaw=-Math.PI/2;walk.pitch=0;walk.route=true;setWalkStation(0)}
function chooseWalkDevice(id,look=true){walk.device=id;const d=equipment.find(e=>e.id===id);if(d?.room)walk.room=d.room;syncIndoorDevices();if(look){const m=walk.fixtures.get(id);if(m){const p=m.position,dx=p.x-walk.x,dz=p.z-walk.z;walk.yaw=Math.atan2(-dx,-dz);walk.pitch=T.MathUtils.clamp(Math.atan2(p.y-1.65,Math.hypot(dx,dz)),-.65,.65)}}drawWalkHUD()}
function drawWalkHUD(){if(!walk.active)return;const r=rooms.find(r=>r.id===walk.room),ds=equipment.filter(d=>d.room===r.id),dev=equipment.find(d=>d.id===walk.device),station=walkStations()[walk.station];walkHUD.innerHTML=`<div class="walk-top"><div><span class="eyebrow">${walk.floor===3?(r.id==='B0-301'?'301 / 3F · 精修示意样板':'3F · 走廊精修示意'):'INDOOR EXPLORER · 示意模型'}</span><h2>教学楼 A <span id="walkLocation">/ ${walk.floor}F / ${Math.abs(walk.z)>2.2?r.code+' 教室':'走廊'}</span></h2></div><div><button id="walkResetPose">复位视角</button><button id="walkGuideToggle">${document.body.classList.contains('walk-route-min')?'展开导览':'收起导览'}</button><button id="walkViewToggle">${document.body.classList.contains('walk-clean')?'恢复面板':'纯净视图'}</button><button id="walkPlan">返回楼层</button><button id="walkExit">返回校园</button></div></div><aside class="walk-info"><div class="walk-section-title">空间导航 <small>FIRST PERSON</small></div><div class="walk-selects"><label>楼层<select id="walkFloor" aria-label="漫游楼层">${[1,2,3,4,5].map(f=>`<option value="${f}" ${f===walk.floor?'selected':''}>${f}F</option>`).join('')}</select></label><label>教室<select id="walkRoom" aria-label="漫游教室">${rooms.filter(x=>x.bi===0&&x.floor===walk.floor).map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${x.code}</option>`).join('')}</select></label></div><div class="walk-settings"><label>速度<select id="walkSpeed" aria-label="行走速度">${[[1.4,'慢速'],[2.1,'舒适'],[3.1,'快速']].map(([v,n])=>`<option value="${v}" ${walk.speed===v?'selected':''}>${n}</option>`).join('')}</select></label><label>转向<select id="walkSensitivity" aria-label="转向灵敏度">${[[.0024,'柔和'],[.0032,'标准'],[.0045,'灵敏']].map(([v,n])=>`<option value="${v}" ${walk.sensitivity===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="walk-dest"><b>${r.code} 教室</b><span class="state-chip ${r.occupied?'':'idle'}">${r.occupied?'使用中':'空闲'}</span></div><div class="walk-values"><div><span>温度</span><b class="${r.temp>30?'warn-text':''}">${r.temp.toFixed(1)}<small>°C</small></b></div><div><span>湿度</span><b>${r.humidity}<small>%</small></b></div><div><span>空气</span><b>${r.aqi}<small>AQI</small></b></div></div><div class="walk-section-title">关联设备 <button id="walkDeviceList">${document.body.classList.contains('walk-devices-open')?'收起清单':'展开清单'}</button></div><div class="walk-devices">${[...ds,...(r.id===hotRoom.id?[equipment.find(d=>d.id==='ENV-N')]:[])].map(d=>`<button data-walk-device="${d.id}" class="${walk.device===d.id?'selected':''}"><span>${{light:'☼',camera:'◉',access:'⌑',sensor:'❖'}[d.type]} ${d.name}</span><small>${statusText(d)}</small></button>`).join('')}</div>${dev?`<div class="walk-device-detail"><b>${dev.name}</b><small>${dev.serial} · ${dev.online?'在线':'离线'}</small><p>${statusText(dev)}</p>${['light','access'].includes(dev.type)?`<button id="walkToggle" ${!dev.online?'disabled':''}>${dev.type==='light'?(dev.running?'关闭照明':'开启照明'):(dev.running?'锁定门禁':'解锁门禁')}（模拟）</button>`:'<span>设备点位为室内示意</span>'}</div>`:''}<div class="walk-note">位置、家具与门洞为示意。门禁控制仅改变模拟状态，门洞保持可通行。</div></aside><div class="walk-crosshair">+</div><button id="walkHint" class="walk-hint" hidden></button><div class="walk-route"><div class="walk-route-heading"><span class="state-chip">${walk.route?'固定路线运行中':walk.station===4?'路线终点 / 自由漫游':'自由漫游 / 路线已暂停'}</span><span>${walk.station+1} / 5</span></div><h3>${station.title}</h3><p>${station.copy}</p><div class="walk-route-actions"><button id="walkRouteStart">${walk.route?'重新开始路线':'固定路线'}</button><button id="walkPause">${walk.route?'暂停路线':walk.station===4?'重走路线':'继续路线'}</button><button id="walkPrev" ${walk.station===0?'disabled':''}>上一站</button><button id="walkNext" ${walk.station===4?'disabled':''}>下一站</button><button id="walkEnterRoom">直达教室</button></div><small>拖动画面转向 · WASD / 方向键移动 · Esc 返回楼层</small></div><div class="walk-move"><button data-walk-move="forward" aria-label="向前行走">↑</button><div><button data-walk-move="left" aria-label="向左行走">←</button><button data-walk-move="back" aria-label="向后行走">↓</button><button data-walk-move="right" aria-label="向右行走">→</button></div></div><div class="walk-floor-map"><span>${walk.floor}F 导览 · N ↑</span><svg viewBox="0 0 240 95" role="img" aria-label="室内所在位置示意"><rect x="2" y="2" width="236" height="90" rx="3" fill="#143d3e88" stroke="#a9d9bb44"/>${rooms.filter(x=>x.bi===0&&x.floor===walk.floor).map(x=>{const p=indoorLocation(x);return `<rect x="${(p.x+24)*4.7+5-24}" y="${p.side<0?7:58}" width="47" height="28" rx="2" fill="${x.id===walk.room?'#b5dca44d':'#7ba9a21a'}" stroke="${roomAlert(x.id)?'#e7bd7b':'#91baa83c'}"/>`}).join('')}<text x="120" y="50" text-anchor="middle" font-size="8" fill="#a6c8c1">公共走廊</text><circle id="walkMapDot" r="3" fill="#e7f4c7"/><path id="walkMapDir" stroke="#e7f4c7" stroke-width="1.5"/></svg><small>模拟数据 · 第一人称视角</small></div>`;
 $('#walkResetPose').onclick=()=>{walk.route=false;walk.keys.clear();walk.vx=walk.vz=0;setWalkStation(0,true)};$('#walkGuideToggle').onclick=()=>{document.body.classList.toggle('walk-route-min');drawWalkHUD()};$('#walkDeviceList').onclick=()=>{document.body.classList.toggle('walk-devices-open');drawWalkHUD()};$('#walkSpeed').onchange=e=>walk.speed=+e.target.value;$('#walkSensitivity').onchange=e=>walk.sensitivity=+e.target.value;$('#walkHint').onclick=()=>{if(walk.nearby){indoorManual();chooseWalkDevice(walk.nearby,false)}};$('#walkViewToggle').onclick=()=>{document.body.classList.toggle('walk-clean');drawWalkHUD()};$('#walkPlan').onclick=()=>exitWalk(true);$('#walkExit').onclick=()=>exitWalk(false);$('#walkFloor').onchange=e=>{walk.floor=+e.target.value;walk.room=rooms.find(x=>x.bi===0&&x.floor===walk.floor).id;walk.device=null;walk.route=false;walk.x=-22;walk.z=0;walk.yaw=-Math.PI/2;walk.pitch=0;walk.station=0;buildIndoor();drawWalkHUD()};$('#walkRoom').onchange=e=>{walk.room=e.target.value;walk.device=null;walk.route=false;setWalkStation(1,true)};document.querySelectorAll('[data-walk-device]').forEach(b=>b.onclick=()=>{walk.route=false;chooseWalkDevice(b.dataset.walkDevice)});if($('#walkToggle'))$('#walkToggle').onclick=()=>{if(!dev.online)return;dev.running=!dev.running;syncIndoorDevices();updateOverview();drawWalkHUD()};$('#walkRouteStart').onclick=startWalkRoute;$('#walkPause').onclick=()=>{if(!walk.route&&walk.station===4){startWalkRoute();return}walk.route=!walk.route;walk.routeHold=0;drawWalkHUD()};$('#walkPrev').onclick=()=>{walk.route=false;setWalkStation(walk.station-1,true)};$('#walkNext').onclick=()=>{walk.route=false;setWalkStation(walk.station+1,true)};$('#walkEnterRoom').onclick=()=>{walk.route=false;setWalkStation(3,true)};document.querySelectorAll('[data-walk-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();walk.route=false;walk.keys.add(b.dataset.walkMove);b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>walk.keys.delete(b.dataset.walkMove)});}
function indoorManual(){if(walk.route){walk.route=false;drawWalkHUD()}}
document.addEventListener('keydown',e=>{if(!walk.active||e.target.matches('select,input,textarea'))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();exitWalk(true);return}if(e.key.toLowerCase()==='e'&&walk.nearby){e.preventDefault();indoorManual();chooseWalkDevice(walk.nearby,false);return}const key={w:'forward',W:'forward',ArrowUp:'forward',s:'back',S:'back',ArrowDown:'back',a:'left',A:'left',ArrowLeft:'left',d:'right',D:'right',ArrowRight:'right'}[e.key];if(key){e.preventDefault();indoorManual();walk.keys.add(key)}},true);
document.addEventListener('keyup',e=>{const key={w:'forward',W:'forward',ArrowUp:'forward',s:'back',S:'back',ArrowDown:'back',a:'left',A:'left',ArrowLeft:'left',d:'right',D:'right',ArrowRight:'right'}[e.key];if(key)walk.keys.delete(key)});window.addEventListener('blur',()=>{walk.keys.clear();walk.drag=false;if(walk.active)indoorManual()});
function updateWalkHint(t){if(t-(walk.lastHint||0)<180)return;walk.lastHint=t;const hint=$('#walkHint'),direction=new T.Vector3();walkCamera.getWorldDirection(direction);let nearest=null,best=3.4;for(const m of walk.pickables){const screen=m.position.clone().project(walkCamera);if(Math.abs(screen.x)>.88||Math.abs(screen.y)>.88||screen.z>1)continue;const v=m.position.clone().sub(walkCamera.position),distance=v.length();if(distance<best&&distance>.12&&v.normalize().dot(direction)>.76){best=distance;nearest=m.userData.walkDevice}}walk.nearby=nearest;if(hint){hint.hidden=!nearest;if(nearest){const d=equipment.find(x=>x.id===nearest);hint.textContent=`E / 点击查看 · ${d.name} · ${d.online?'在线':'离线'}`}}}

function animateIndoor(t){const dt=walk.last?Math.min((t-walk.last)/1000,.05):.016;walk.last=t;if(walk.route){const p=walkStations()[walk.station],dx=p.x-walk.x,dz=p.z-walk.z,distance=Math.hypot(dx,dz);if(distance>.035){const speed=Math.min(distance,dt*2.4);advanceWalk(dx/distance*speed,dz/distance*speed)}let a=((p.yaw-walk.yaw+Math.PI*3)%(Math.PI*2))-Math.PI;walk.yaw+=a*Math.min(1,dt*3);walk.pitch+=(p.pitch-walk.pitch)*Math.min(1,dt*3);if(distance<.06){walk.routeHold+=dt;if(walk.routeHold>5){if(walk.station<4)setWalkStation(walk.station+1);else {walk.route=false;drawWalkHUD()}}}}else{let f=(walk.keys.has('forward')?1:0)-(walk.keys.has('back')?1:0),s=(walk.keys.has('right')?1:0)-(walk.keys.has('left')?1:0),n=Math.hypot(f,s)||1;const response=1-Math.exp(-dt*10),speed=walk.speed||2.1;walk.vx=(walk.vx||0)+(((-Math.sin(walk.yaw)*f+Math.cos(walk.yaw)*s)*speed/n)-(walk.vx||0))*response;walk.vz=(walk.vz||0)+(((-Math.cos(walk.yaw)*f-Math.sin(walk.yaw)*s)*speed/n)-(walk.vz||0))*response;advanceWalk(walk.vx*dt,walk.vz*dt)}walk.yaw=T.MathUtils.euclideanModulo(walk.yaw+Math.PI,Math.PI*2)-Math.PI;if(!walk.route&&Math.abs(walk.z)>2.3){const inside=rooms.filter(r=>r.bi===0&&r.floor===walk.floor).find(r=>{const p=indoorLocation(r);return Math.abs(walk.x-p.x)<5.9&&Math.sign(walk.z)===p.side});if(inside&&inside.id!==walk.room){walk.room=inside.id;walk.device=null;syncIndoorDevices();drawWalkHUD()}}const location=$('#walkLocation');if(location)location.textContent='/ '+walk.floor+'F / '+(Math.abs(walk.z)>2.2?rooms.find(r=>r.id===walk.room).code+' 教室':'走廊');walkCamera.position.set(walk.x,1.65,walk.z);walkCamera.rotation.order='YXZ';walkCamera.rotation.set(walk.pitch,walk.yaw,0);walkCamera.updateMatrixWorld();updateWalkHint(t);const dot=$('#walkMapDot'),dir=$('#walkMapDir'),mx=5+(walk.x+24)*4.7,my=47+walk.z*4.5;if(dot){dot.setAttribute('cx',mx);dot.setAttribute('cy',my);dir.setAttribute('d',`M${mx} ${my}l${-Math.sin(walk.yaw)*9} ${-Math.cos(walk.yaw)*9}`)}renderer.render(walkScene,walkCamera)}
const indoorLauncher=document.createElement('button');indoorLauncher.id='indoorLauncher';indoorLauncher.textContent='⌂ 室内漫游';$('.tools').prepend(indoorLauncher);indoorLauncher.onclick=()=>openWalk('B0-301');

let down=false,moved=false,last={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>{if(walk.active){indoorManual();walk.drag=true;walk.dragMoved=false;last={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);return}down=true;moved=false;last={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(walk.active){if(walk.drag){const dx=e.clientX-last.x,dy=e.clientY-last.y;walk.yaw-=dx*(walk.sensitivity||.0032);walk.pitch=T.MathUtils.clamp(walk.pitch-dy*(walk.sensitivity||.0032)*.75,-.75,.75);if(Math.abs(dx)+Math.abs(dy)>2)walk.dragMoved=true;last={x:e.clientX,y:e.clientY}}return}if(!down)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;angle-=dx*.006;elevation=T.MathUtils.clamp(elevation+dy*.004,.25,1.35);last={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(walk.active){walk.drag=false;if(!walk.dragMoved){const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),walkCamera);const hit=ray.intersectObjects(walk.pickables)[0];if(hit)chooseWalkDevice(hit.object.userData.walkDevice,false)}return}down=false;if(moved)return;let p=new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),ray=new T.Raycaster();ray.setFromCamera(p,camera);let hit=ray.intersectObjects([...buildings.filter(g=>g.visible),...(spatial.expanded?floorGroups.filter(g=>g.visible):[])],true)[0];if(hit){if(hit.object.userData.spatial){const u=hit.object.userData;if(u.roomId)chooseSpatialRoom(u.roomId);else{spatial.floor=u.floor;spatial.room=rooms.find(r=>r.bi===0&&r.floor===u.floor).id;renderSpatial()}}else select(hit.object.userData.id)}});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();if(walk.active)return;desiredRadius=T.MathUtils.clamp(desiredRadius+e.deltaY*.15,110,460)},{passive:false});renderer.domElement.style.touchAction='none';window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();walkCamera.aspect=innerWidth/innerHeight;walkCamera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});function clock(){$('#clock').textContent=new Date().toLocaleString('zh-CN',{hour12:false})}clock();setInterval(clock,1000);setInterval(()=>$('#temp').innerHTML=(24.8+(Math.random()-.5)*.4).toFixed(1)+'<small>°C</small>',6000);function animate(t){requestAnimationFrame(animate);if(walk.active){animateIndoor(t);return}if(auto)angle+=.0012;target.lerp(desiredTarget,.045);radius+=(desiredRadius-radius)*.045;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*radius,target.y+Math.sin(elevation)*radius,target.z+Math.cos(angle)*Math.cos(elevation)*radius);camera.lookAt(target);marker.material.opacity=.5+Math.sin(t*.003)*.3;beacon.scale.setScalar(1+Math.sin(t*.003)*.18);camera.updateMatrixWorld();animateSpatial();labels.forEach(({el,p},i)=>{let q=p.clone().project(camera);el.style.left=(q.x*.5+.5)*innerWidth+'px';el.style.top=(-q.y*.5+.5)*innerHeight+'px';el.style.display=q.z>1||q.x<-1||q.x>1||(spatial.expanded&&i===0)||(![0,2,4].includes(i)&&i!==selected)?'none':'block'});renderer.render(scene,camera)}animate(0);
